var needle=require(".."),https=require("https"),helpers=require("./helpers"),should=require("should");describe("tls options",function(){describe("rejectUnauthorized: false",function(){var e="https://expired-rsa-dv.ssl.com/";it("is an expired cert",function(t){needle.get(e,function(e,n){e.code.should.eql("CERT_HAS_EXPIRED"),should.not.exist(n),t()})}),it("allows fetching pages under expired certificates",function(t){needle.get(e,{rejectUnauthorized:!1},function(e,n){should.not.exist(e),n.statusCode.should.eql(200),t()})}),it("also works when using custom agent",function(t){new https.Agent({rejectUnauthorized:!0}),needle.get(e,{rejectUnauthorized:!1},function(e,n){should.not.exist(e),n.statusCode.should.eql(200),t()})}),it("also works with shared/default agent",function(t){var n=new https.Agent({rejectUnauthorized:!0});needle.defaults({agent:n}),needle.get(e,{rejectUnauthorized:!1},function(e,n){should.not.exist(e),n.statusCode.should.eql(200),needle.defaults({agent:null}),t()})})})});